// Sample dataset for the demo MCP server.
// Mirrors Vedette's evidence-grounded pattern: every opportunity traces to a
// source chunk, and dollar figures are never generated by the model, only by
// computeRoi() in roi.ts. This is seeded demo data, not a live database —
// swap this file for a real Supabase query when connecting to production data.

export interface EvidenceChunk {
  id: string;
  documentTitle: string;
  text: string;
}

export interface Opportunity {
  id: string;
  title: string;
  description: string;
  evidenceIds: string[]; // which chunks support this opportunity
  hoursPerWeekSaved: number; // proposed by analysis, not computed
  peopleAffected: number;
}

